def count_passing_ways(n: int, m: int) -> int:
    if m == 0:
        return 1
    if n == 1:
        return 1 << m  # 2**m
    dp = [0] * n
    dp[0] = 1
    for _ in range(m):
        next_dp = [0] * n
        for pos, val in enumerate(dp):
            if val:
                next_dp[(pos + 1) % n] += val
                next_dp[(pos - 1) % n] += val
        dp = next_dp
    return dp[0]

