    dp = [0] * n
    dp[0] = 1
    for _ in range(m):
        new = [0] * n
        for i, val in enumerate(dp):
            if val:
                left = (i - 1) % n
                right = (i + 1) % n
                new[left] += val
                new[right] += val
        dp = new
    return dp[0]

