def catalan_number(n: int) -> int:
    """Return the nth Catalan number using dynamic programming."""
    if n < 0:
        raise ValueError("n must be non-negative")
    # Base case: C(0) = 1
    catalan = [1]  # catalan[0] = 1
    for i in range(1, n + 1):
        total = 0
        for j in range(i):
            total += catalan[j] * catalan[i - 1 - j]
        catalan.append(total)
    return catalan[n]

def catalan_number(n: int) -> int:
    if n < 0:
        raise ValueError("n must be a non-negative integer")
    catalan = [0] * (n + 1)
    catalan[0] = 1
    for i in range(1, n + 1):
        total = 0
        for j in range(i):
            total += catalan[j] * catalan[i - 1 - j]
        catalan[i] = total
    return catalan[n]

def count_apples_reachable(apple_heights: List[int], tao_reach: int) -> int:
    max_reach = tao_reach + 30
    count = 0
    for height in apple_heights:
